#[test]
fn test_case_0001() {
    let options: Vec<OptionDef> = (0..32)
        .map(|k| OptionDef {
            id: format!("opt_{k}"),
            description: format!(
                "Microservice deployment target cluster handler {k} with failover logic"
            ),
        })
        .collect();
    let shortlisted = shortlist_options(
        &options,
        "critical incident alert on opt_3 cluster failure",
        6,
    );
    assert!(shortlisted.len() <= 6);
    assert!(!shortlisted.is_empty());
    assert!(shortlisted.iter().any(|o| o.id == "opt_3"));
}

