#[test]
fn test_case_0201() {
    let engine = ZevEngine::default();
    let options: Vec<OptionDef> = (0..506)
        .map(|k| OptionDef {
            id: format!("server_route_{k}"),
            description: format!("Traffic gateway load balancer ingress route node {k}"),
        })
        .collect();
    let policy = Policy {
        max_slots: Some(35),
        ..Policy::default()
    };
    let q = Question::Choice(ChoiceQuestion {
        instructions: "Select the failing server route".into(),
        options,
        policy,
    });
    let req = ZevRequest {
        state: "Host telemetry alert: high memory saturation on server_route_43".into(),
        questions: [("selection".into(), q)].into(),
        model: None,
        temperature: None,
        enable_temporal_facts: false,
    };
    let res = engine.evaluate(&req).unwrap();
    assert_eq!(
        res.answers["selection"]
            .decision
            .as_ref()
            .and_then(|v| v.as_str()),
        Some("server_route_43")
    );
}

