#[test]
fn test_case_0351() {
    let mut state = String::with_capacity(2240);
    for line in 0..32 {
        state.push_str(&format!("2026-09-24T01:00:{:02}Z [INFO] system background heartbeat thread {} normal operation\n", line % 60, line));
    }
    state.push_str(
        "2026-09-24T01:45:00Z [CRITICAL] proc_svc_11 crashed with exit status 137 OOMKilled\n",
    );
    let engine = ZevEngine::default();
    let options = vec![
        OptionDef {
            id: "proc_svc_0".into(),
            description: "processing service instance 0".into(),
        },
        OptionDef {
            id: "proc_svc_11".into(),
            description: "critical microservice crashed by oom".into(),
        },
        OptionDef {
            id: "auth_proxy".into(),
            description: "authentication gateway proxy".into(),
        },
    ];
    let q = Question::Choice(ChoiceQuestion {
        instructions: "Identify crashed service".into(),
        options,
        policy: Policy::default(),
    });
    let req = ZevRequest {
        state: state.into(),
        questions: [("root_cause".into(), q)].into(),
        model: None,
        temperature: None,
        enable_temporal_facts: false,
    };
    let res = engine.evaluate(&req).unwrap();
    assert_eq!(
        res.answers["root_cause"]
            .decision
            .as_ref()
            .and_then(|v| v.as_str()),
        Some("proc_svc_11")
    );
}

