#[test]
fn test_case_1151() {
    let mut arena = VectorArena::new(21, 32);
    for k in 0..101 {
        let vec: Vec<f32> = (0..32).map(|x| ((x + k) as f32).sin()).collect();
        arena.insert(&format!("vector_{k}"), &vec);
    }
    assert_eq!(arena.len(), 21);
    assert_eq!(arena.capacity(), 21);
    let stats = arena.stats();
    assert_eq!(stats.used, 21);
    assert!(stats.evictions > 0);

    let query: Vec<f32> = (0..32).map(|x| (x as f32).cos()).collect();
    let keys = vec!["vector_49", "vector_50", "vector_nonexistent"];
    let scores = arena.score_keys(&query, &keys);
    assert_eq!(scores.len(), 3);
}

