#[test]
fn test_case_1351() {
    let config = HeadConfig {
        input_dim: 128,
        hidden_dim: 256,
        projection_dim: 32,
        logit_scale: 2.1,
    };
    let head = ContrastiveHead::new(config);
    let x: Vec<f32> = (0..128).map(|v| (v as f32 * 0.1).sin()).collect();
    let proj = head.project(&x);
    assert_eq!(proj.len(), 32);
    let norm: f32 = proj.iter().map(|v| v * v).sum::<f32>().sqrt();
    assert!(
        (norm - 1.0).abs() < 1e-4,
        "Projected vector must be L2 normalized"
    );

    let y: Vec<f32> = (0..128).map(|v| (v as f32 * 0.2).cos()).collect();
    let proj_y = head.project(&y);
    let score = head.score(&proj, &proj_y);
    assert!(!score.is_nan() && !score.is_infinite());
}

