#[test]
fn test_case_1751() {
    let engine = ZevEngine::default();
    let options = vec![
        OptionDef {
            id: "app".into(),
            description: "short app prefix token_1751".into(),
        },
        OptionDef {
            id: "apple".into(),
            description: "apple fruit token_1751".into(),
        },
        OptionDef {
            id: "application".into(),
            description: "application software deployment token_1751".into(),
        },
        OptionDef {
            id: "applicable".into(),
            description: "legally applicable regulation token_1751".into(),
        },
    ];
    let q = Question::Choice(ChoiceQuestion {
        instructions: "Identify exact match".into(),
        options,
        policy: Policy::default(),
    });
    // Test that 'application' does not trigger false positive on 'app' or 'apple'
    let req = ZevRequest {
        state:
            "We are currently updating the enterprise application software deployment token_1751"
                .into(),
        questions: [("matched".into(), q)].into(),
        model: None,
        temperature: None,
        enable_temporal_facts: false,
    };
    let res = engine.evaluate(&req).unwrap();
    assert_eq!(
        res.answers["matched"]
            .decision
            .as_ref()
            .and_then(|v| v.as_str()),
        Some("application")
    );
}

